#!/usr/bin/env bash
# Create gem5 checkpoints for one benchmark suite (SPEC or adversarial).
#
# Flip SUITE below to switch between suites. Everything else is derived
# from it. To change an individual path, edit that line directly.
#
# Uses the benchmark-level checkpoint lists generated by:
#   configs/peregrine/gen_sim_sweep.py
# and performs one gem5 call per benchmark using:
#   --take-checkpoint --checkpoints "<comma-separated list>"
#
# Each successful run leaves:
#   <CHECKPOINT_DIR>/<bench>/cpt.<instructions>/m5.cpt
#   <CHECKPOINT_DIR>/<bench>/cpt.<instructions>/board.physmem.store0.pmem

set -euo pipefail

# ---------- suite selection (edit this line) --------------------------------
SUITE="adversarial"   # "spec" or "adversarial"

# ---------- shared paths ----------------------------------------------------
GEM5_ROOT="/home/ubuntu/peregrine-gem5"
GEM5_BIN="$GEM5_ROOT/build/X86/gem5.opt"

# ---------- suite-derived paths ---------------------------------------------
case "$SUITE" in
  spec)
    CHECKPOINT_DIR="$GEM5_ROOT/configs/peregrine/spec_checkpoints"
    CHECKPOINT_OUT_BASE="$GEM5_ROOT/configs/peregrine/checkpoints_outputs"
    CHECKPOINT_SWEEP_CSV="$GEM5_ROOT/configs/peregrine/sim_checkpoint_sweep.csv"
    ;;
  adversarial)
    CHECKPOINT_DIR="$GEM5_ROOT/configs/peregrine/adversarial_checkpoints"
    CHECKPOINT_OUT_BASE="$GEM5_ROOT/configs/peregrine/checkpoints_outputs"
    CHECKPOINT_SWEEP_CSV="$GEM5_ROOT/configs/peregrine/sim_checkpoint_sweep.csv"
    ;;
  *)
    echo "Unknown SUITE='$SUITE' (expected 'spec' or 'adversarial')" >&2
    exit 1
    ;;
esac
export GEM5_ROOT GEM5_BIN CHECKPOINT_DIR CHECKPOINT_OUT_BASE CHECKPOINT_SWEEP_CSV

# ---------- pre-flight ------------------------------------------------------
if ! command -v parallel &>/dev/null; then
  echo "GNU parallel is required. Install with: apt install parallel" >&2
  exit 1
fi

if [[ ! -d "$GEM5_ROOT" ]]; then
  echo "GEM5_ROOT not found: $GEM5_ROOT" >&2
  exit 1
fi

cd "$GEM5_ROOT"

if [[ ! -x "$GEM5_BIN" ]]; then
  echo "gem5 binary not found or not executable: $GEM5_BIN" >&2
  echo "Build it first, e.g.: scons build/X86/gem5.opt -j \$(nproc)" >&2
  exit 1
fi

if [[ ! -f "$CHECKPOINT_SWEEP_CSV" ]]; then
  echo "Checkpoint sweep CSV not found: $CHECKPOINT_SWEEP_CSV" >&2
  echo "Generate it first with configs/peregrine/gen_sim_sweep.py" >&2
  exit 1
fi

mkdir -p "$CHECKPOINT_DIR"

run_bench() {
  local bench="$1"
  local checkpoints_csv="$2"

  local outdir="$CHECKPOINT_OUT_BASE/m5out_${bench}"
  rm -rf "$outdir"
  mkdir -p "$outdir"
  local stdout_file="$outdir/gem5_stdout.log"

  local checkpoint_dir="$CHECKPOINT_DIR/${bench}"

  echo "Checkpointing benchmark: $bench"
  set +e
  (
    cd "$GEM5_ROOT" || exit 1
    "$GEM5_BIN" --redirect-stdout --stdout-file="$stdout_file" configs/peregrine/peregrine.py \
      --benchmark "$bench" \
      --outdir "$outdir" \
      --take-checkpoint \
      --checkpoints "$checkpoints_csv" \
      --checkpoint-dir "$checkpoint_dir"
  )
  local gem_status=$?
  set -e

  if [[ $gem_status -eq 0 ]]; then
    rm -f "$stdout_file"
  else
    echo "gem5.opt failed (status $gem_status) for benchmark=$bench; stdout log: $stdout_file" >&2
    return "$gem_status"
  fi

  if [[ ! -d "$checkpoint_dir" ]]; then
    echo "Checkpoint directory not created: $checkpoint_dir" >&2
    return 1
  fi

  local IFS=','
  read -r -a checkpoint_points <<< "$checkpoints_csv"
  local inst cpt_dir cpt_file pmem_file
  for inst in "${checkpoint_points[@]}"; do
    cpt_dir="$checkpoint_dir/cpt.${inst}"
    cpt_file="$cpt_dir/m5.cpt"
    pmem_file="$cpt_dir/board.physmem.store0.pmem"
    if [[ ! -d "$cpt_dir" ]]; then
      echo "Checkpoint subdirectory not found: $cpt_dir" >&2
      return 1
    fi
    if [[ ! -f "$cpt_file" ]]; then
      echo "Checkpoint file not found: $cpt_file" >&2
      return 1
    fi
    if [[ ! -f "$pmem_file" ]]; then
      echo "Physical memory file not found: $pmem_file" >&2
      return 1
    fi
  done

  echo "$bench checkpoints created successfully in: $checkpoint_dir"

  rm -rf "$outdir"
}

export -f run_bench

# Print "benchmark<TAB>checkpoints" rows from the checkpoint sweep CSV.
generate_benchmark_rows() {
  awk '
    BEGIN {
      have_benchmark = 0
      have_checkpoints = 0
    }
    NR == 1 {
      n = split($0, header_cols, ",")
      for (i = 1; i <= n; i++) {
        if (header_cols[i] == "benchmark") {
          have_benchmark = 1
        }
        if (header_cols[i] == "checkpoints") {
          have_checkpoints = 1
        }
      }
      if (!have_benchmark || !have_checkpoints) {
        print "CSV missing required columns: benchmark, checkpoints" > "/dev/stderr"
        exit 1
      }
      next
    }
    {
      line = $0
      sub(/\r$/, "", line)

      bench = line
      sub(/,.*/, "", bench)

      checkpoints = line
      sub(/^[^,]*,[^,]*,[^,]*,/, "", checkpoints)
      gsub(/^"/, "", checkpoints)
      gsub(/"$/, "", checkpoints)

      if (bench != "" && checkpoints != "") {
        print bench "\t" checkpoints
      }
    }
  ' "$CHECKPOINT_SWEEP_CSV"
}

generate_benchmark_rows | parallel -j "$(nproc)" --colsep '\t' \
  --env GEM5_ROOT --env GEM5_BIN --env CHECKPOINT_DIR --env CHECKPOINT_OUT_BASE --env CHECKPOINT_SWEEP_CSV --env run_bench \
  run_bench {1} {2}


rm -rf "$CHECKPOINT_OUT_BASE"

echo "Done. Checkpoints in $CHECKPOINT_DIR"
